import Foundation

/// تاريخ هجري
public struct HDate: Hashable, Codable, CustomStringConvertible, Sendable {
    public let y: Int
    public let m: Int
    public let d: Int
    public init(y: Int, m: Int, d: Int) { self.y = y; self.m = m; self.d = d }
    public init(_ y: Int, _ m: Int, _ d: Int) { self.y = y; self.m = m; self.d = d }
    public var description: String { "HDate(y=\(y), m=\(m), d=\(d))" }
}

/// التقويم الهجري وفق أم القرى من 1300 إلى 1600 هـ (الجدول مأخوذ من java.time.chrono.HijrahChronology). أسماء الأشهر في ملفات اللغة.
public enum Hijri {
    public static let firstYear = 1300
    public static let lastYear = 1600
    /// يوم 1 محرم 1300 بعدد الأيام منذ 1970-01-01
    private static let epochStart = -31826

    /// طول كل شهر من محرم 1300 إلى ذي الحجة 1600: 1 = ثلاثون يوماً، 0 = تسعة وعشرون
    private static let lengths: [Bool] = Array("").map { $0 == "1" }

    /// بداية كل شهر بعدد الأيام منذ 1970 (عنصر إضافي في الآخر لنهاية الجدول)
    private static let starts: [Int] = {
        var a = [Int](repeating: 0, count: lengths.count + 1)
        a[0] = epochStart
        for i in 0..<lengths.count { a[i + 1] = a[i] + (lengths[i] ? 30 : 29) }
        return a
    }()

    /// التاريخ الهجري لتاريخ ميلادي، أو nil خارج الجدول
    public static func toHijri(_ date: LocalDate) -> HDate? {
        let day = date.epochDay
        let s = starts
        if day < s[0] || day >= s[s.count - 1] { return nil }
        var lo = 0, hi = s.count - 2
        while lo < hi { let mid = (lo + hi + 1) / 2; if s[mid] <= day { lo = mid } else { hi = mid - 1 } }
        return HDate(firstYear + lo / 12, lo % 12 + 1, day - s[lo] + 1)
    }

    private static func index(_ y: Int, _ m: Int) -> Int? {
        (y >= firstYear && y <= lastYear && m >= 1 && m <= 12) ? (y - firstYear) * 12 + (m - 1) : nil
    }

    /// التاريخ الميلادي لتاريخ هجري، أو nil إن لم يكن صحيحاً أو كان خارج الجدول
    public static func toGregorian(_ y: Int, _ m: Int, _ d: Int) -> LocalDate? {
        guard let i = index(y, m) else { return nil }
        if d < 1 || d > monthLength(y, m) { return nil }
        return LocalDate(epochDay: starts[i] + d - 1)
    }

    public static func toGregorian(_ h: HDate) -> LocalDate? { toGregorian(h.y, h.m, h.d) }

    /// طول الشهر الهجري (30 خارج الجدول)
    public static func monthLength(_ y: Int, _ m: Int) -> Int {
        guard let i = index(y, m) else { return 30 }
        return lengths[i] ? 30 : 29
    }
}
